"Nothing playing": "Ничего не играет",
"Play this song now (the player keeps what it was playing until you do). Double-clicking a song in the list plays it too.": "Сыграть эту песню сейчас (до того плеер играет своё). Двойной щелчок по песне в списке тоже её играет.",
