"Replace this section…": "Заменить эту секцию…",
"Replace a section": "Замена секции",
"Its words as the lyrics have them: change what you will, and it is sung anew from its start to its end; the rest of the take stays as it is.": "Её слова, как они стоят в лирике: измени что хочешь, и она будет спета заново от начала до конца; остальное в дубле останется как есть.",
"Two versions": "Две версии",
"One version": "Одна версия",
"Sing it anew": "Спеть заново",
"More syllables than the section held: the model sings them faster, or runs over the cut": "Слогов больше, чем держала секция: модель споёт их быстрее или заступит за шов",
"Fewer syllables than the section held: the model may stretch them or leave a rest": "Слогов меньше, чем держала секция: модель может растянуть их или оставить паузу",
"Sung anew: its versions come as takes of their own, children of this one": "Поётся заново: версии придут отдельными дублями, детьми этого",
"Sung anew here (Replace a section); the rest is as its parent made it": "Здесь спето заново (замена секции); остальное — как сделал родитель",
"anew": "заново",
"This section cannot be replaced: its lines were not heard clearly": "Эту секцию нельзя заменить: её строки не расслышаны ясно",
"Epochs": "Эпохи",
"How many epochs: every track of the set once an epoch, one track a step; the run's steps are the set's tracks times this. A small set is learnt by heart fast: the green epochs in the Telemetry are the ones to hear first, often before the last.": "Сколько эпох: каждый трек сета по разу за эпоху, по треку на шаг; шагов у прогона столько, сколько треков в сете, умноженное на это. Маленький сет быстро заучивается наизусть: зелёные эпохи в Телеметрии слушать первыми, часто раньше последней.",
"Cancel this run?": "Отменить этот запуск?",
"What the engine has made of it so far is lost.": "Что движок успел сделать, пропадёт.",
