"Retake: this take is in the form with its music codes, so Generate renders that music again. Drop the codes to write new music.": "Новый семпл: этот семпл в форме со своими музыкальными кодами, поэтому «Создать» озвучит ту же музыку снова. Сбрось коды, чтобы написать новую.",
"Reuse: prompt, lyrics and settings are in the form, with no score, seeds or music codes. Generate writes a new song from them.": "Взять за основу: промпт, текст и настройки в форме, без партитуры, сидов и музыкальных кодов. «Создать» напишет по ним новую песню.",
