"It takes a GPU of its own for hours; a set without its latent cache gets one first (a second or two a track).": "Он занимает свою GPU на часы; набор без латентного кэша сперва получает его (секунда-две на дорожку).",
"It takes a GPU of its own for hours; the first run also fetches Comfy-Org’s YuE2 weights.": "Он занимает свою GPU на часы; первый ран ещё и скачивает веса YuE2 от Comfy-Org.",
"Training may take GPU{0}, the studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "Тренировка может занять GPU{0}, собственную карту студии: тогда синтез ждёт конца рана (Движок → GPU даст тренировке другую карту).",
"Start training": "Начать тренировку",
"Training {0}": "Тренируется {0}",
"Listener": "Слушатель",
"drafts each track’s style from what it hears; a draft, read and correct it": "набрасывает стиль каждой дорожки по услышанному; это черновик, прочти и поправь",
"Trigger": "Триггер",
"Shared line": "Общая строка",
"after the track’s tags": "после тегов дорожки",
"the album’s vibe": "настроение альбома",
"Write into the captions": "Записать в подписи",
"Listening… {0} / {1}": "Слушает… {0} / {1}",
"Listen to {0}": "Слушать {0}",
"Listen to {0}?": "Слушать {0}?",
"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni слушает по 120 с каждой дорожки и набрасывает её стиль. Прежние наброски откладываются в сторону (styles.DATE.json); подписи меняются, только когда ты их запишешь.",
"Listen": "Слушать",
"Listening to {0}": "Слушается {0}",
"Write {#0} styles into the captions of {1}?": "Записать стили ({0}) в подписи набора {1}?",
"Each first line becomes: {0} The lyrics stay.": "Каждая первая строка станет такой: {0} Текст остаётся.",
"Write": "Записать",
"{#0} captions written": { "one": "Записана {0} подпись", "few": "Записано {0} подписи", "many": "Записано {0} подписей", "other": "Записано {0} подписи" },
"drafts here by {0}": "наброски здесь — {0}",
"The studio’s trainer is missing {0}:": "Тренеру студии не хватает: {0}:",
"Comfy-Org's YuE2 {0} weights": "весов YuE2 {0} от Comfy-Org",
"the realaudio tokenizer head": "головы токенизатора realaudio",
"and": "и",
"AI-Toolkit is not found at": "AI-Toolkit не найден в",
": clone ostris/ai-toolkit there (or set AITK_ROOT for the lab), or train with the studio’s own trainer.": ": склонируй туда ostris/ai-toolkit (или задай AITK_ROOT для лаборатории) либо тренируй собственным тренером студии.",
"The realaudio tokenizer is missing from": "Токенизатора realaudio нет в",
"{#0} characters, about {#1} tokens.": "Символов: {0}, токенов: около {1}.",
"Style and lyrics together: about {#0} of {#1} tokens.": "Стиль и текст вместе: около {0} из {1} токенов.",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Стиль и текст вместе: около {0} из {1} токенов — слишком длинно для полной песни с партитурой.",
"Unlike the model's training styles:": "Не похоже на стили, на которых училась модель:",
"longer than 1,600 characters (the official examples stop at 999)": "длиннее 1 600 символов (официальные примеры кончаются на 999)",
"{#0} Unicode arrow (→): write -> instead": "Unicode-стрелок (→): {0}: пиши -> вместо них",
"{#0} Unicode arrows (→): write -> instead": "Unicode-стрелок (→): {0}: пиши -> вместо них",
"dynamics marks (never in the official styles)": "знаки динамики (в официальных стилях их нет)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "полей «Label:»: {0} (такие есть в 5 из 110 официальных стилей)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "строк в скобках в тексте с «Label:», стрелкой или знаком p/f: {0} (в официальных примерах таких нет)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "строк в скобках в тексте с «Label:», стрелкой или знаком p/f: {0} (в официальных примерах таких нет)",
"{#0} instruments": { "one": "{0} инструмент", "few": "{0} инструмента", "many": "{0} инструментов", "other": "{0} инструмента" },
"{#0} heard": "услышано: {0}",
"{#0} questioned": "под вопросом: {0}",
"{#0} not identified": "не опознано: {0}",
"{#0} not judged yet": "ещё не оценено: {0}",
"the Librarian does not answer: no probes to play": "Библиотекарь не отвечает: проб для прослушивания нет",
"{#0} styles": { "one": "{0} стиль", "few": "{0} стиля", "many": "{0} стилей", "other": "{0} стиля" },
"{#0} style": { "one": "{0} стиль", "few": "{0} стиля", "many": "{0} стилей", "other": "{0} стиля" },
"what a probe gave instead of its instrument": "что проба дала вместо своего инструмента",
"Nothing matches.": "Ничего не подходит.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Имя в стиле — просьба, а не обещание. То, что играют ▶ A и ▶ B, YuE2 даёт на неё примерно девять раз из десяти.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Некоторые пробы великолепны, A и B согласны, а инструмент не тот, о котором просили: верь уху, а не имени.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Что YuE2 просили сыграть — по одному инструменту или стилю, пробами по две минуты (первые — по минуте), с двумя сидами каждая, A и B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Инструмент лепит стиль всей вещи: назвав его, сдвигаешь и аранжировку. Треск или шорох бумаги, как на заезженной пластинке, — неудачный сид: сделай заново на другом.",
"Search: name, home, sound": "Поиск: имя, родина, звук",
