"Remove from the list (the adapter stays in its Trainer session)": "Убрать из списка (адаптер остаётся в своей сессии Тренера)",
"Out of the list; its checkpoint stays in the Trainer's run {0} (the Trainer puts it back)": "Убран из списка; его чекпоинт остаётся в ране Тренера {0} (Тренер вернёт его)",
"muted": "заглушён",
