"Its trigger word goes at the style’s end by itself when the song is made": "Его слово-триггер само встанет в конец стиля, когда песня делается",
"{0}: its trigger word “{1}” goes at the style's end when the song is made.": "{0}: его слово-триггер «{1}» встанет в конец стиля, когда песня делается.",
"Style as tags": "Стиль тегами",
