"Save the brief": "Сохранить запрос",
"A name to find it by under the brief.": "Имя, по которому его найти под запросом.",
"Brief saved: {0}": "Запрос сохранён: {0}",
"Delete the brief “{0}”?": "Удалить запрос «{0}»?",
