"Remember the key in this browser. Otherwise it lives only until the page is closed. The page sends it to openrouter.ai and nowhere else: not to the studio, not into its settings file.": "Запомнить ключ в этом браузере. Иначе он живёт лишь до закрытия страницы. Страница отправляет его только на openrouter.ai: ни в студию, ни в её файл настроек.",
"Any model of openrouter.ai/models, written provider/model. The field offers the list as you type; the quick picks fill it in.": "Любая модель с openrouter.ai/models в виде провайдер/модель. Поле предлагает список по мере набора; быстрые выборы заполняют его.",
"The section order the model gives new lyrics. «Keep mine» leaves the lyrics' own order.": "Порядок разделов, который модель даёт новому тексту. «Оставить мой» сохраняет порядок самого текста.",
"The draft's style as tags, the most important first, as an SD/SDXL prompt is written. «Into the form» chooses which of the two, the tags or the readable style, the draft puts in the Style field.": "Стиль черновика тегами, самое важное первым, как пишется промпт SD/SDXL. «В форму» выбирает, что из двух — теги или читаемый стиль — черновик положит в поле стиля.",
"Your saved briefs, kept by the lab (every browser sees them): picking one puts it in the box above.": "Твои сохранённые запросы, их хранит лаборатория (их видит любой браузер): выбранный встаёт в поле выше.",
"The writing room works on the song in the Creator: “{0}”.": "Комната письма работает с песней в Творце: «{0}».",
"The notebook has “{0}” open. Put it into the Creator and send the request on it?": "В блокноте открыт «{0}». Положить его в Творца и отправить запрос на нём?",
"Put it in and send": "Положить и отправить",
