"the song as words and knobs: style, lyrics, score and sound; Generate makes it, Takes keep it": "песня словами и ручками: стиль, текст, партитура и звук; «Сгенерировать» создаёт её, «Семплы» хранят",
"the take in hand, heard and mended: spectrum, artifacts, stems, remaster, upscale, lyrics check": "семпл в руках, выслушан и поправлен: спектр, артефакты, стемы, ремастер, апскейл, проверка текста",
