"How each step is taken. Euler: the plain step; Euler SDE: fresh noise each step (soft on Qwen without Lightning). ER-SDE: a stochastic solver of third order, one look a step. RES 2s and 3s: the refined exponential solver, two or three looks a step (ODE: without noise). Heun++: up to three looks a step. Exp Heun 2 x0: the exponential Heun, two looks (SDE: with noise). More looks: finer, and as many times longer": "Как делается каждый шаг. Euler: простой шаг; Euler SDE: свежий шум на каждом шаге (мягко на Qwen без Lightning). ER-SDE: стохастический решатель третьего порядка, один взгляд на шаг. RES 2s и 3s: уточнённый экспоненциальный решатель, два или три взгляда на шаг (ODE: без шума). Heun++: до трёх взглядов на шаг. Exp Heun 2 x0: экспоненциальный Heun, два взгляда (SDE: с шумом). Больше взглядов — тоньше и во столько же раз дольше",
"How the steps are spread from the noise to the picture: Simple (the painter's own), Karras and Exponential (more steps near the end, for detail; with Lightning they can paint the subject twice), Beta and Beta 57 (more at both ends), KL optimal (Align Your Steps' spacing), SGM uniform (even in time), Bong tangent (two slopes, through the middle)": "Как шаги распределены от шума до картинки: Simple (родное у художника), Karras и Exponential (больше шагов к концу, ради деталей; с Lightning могут нарисовать сюжет дважды), Beta и Beta 57 (больше на обоих концах), KL optimal (расстановка Align Your Steps), SGM uniform (ровно по времени), Bong tangent (два склона, через середину)",
