"Without Lightning: how closely the picture follows the prompt (true CFG, two passes a step); 4 is Qwen-Image's own": "Без Lightning: насколько точно картинка следует промпту (настоящий CFG, два прохода на шаг); 4 — родное у Qwen-Image",
