"The update fetches it, builds it and restarts the studio when nothing runs; your songs, models and settings stay.": "Обновление скачает её, соберёт и перезапустит студию, когда ничего не идёт; твои песни, модели и настройки останутся.",
"Here it cannot update by itself: {0}.": "Здесь она не обновится сама: {0}.",
"this is a development tree (its origin is not {0}): update it by hand": "это дерево исходников, а не клон релиза (его origin — не {0}): обновляй вручную",
"this studio is not a git clone: update it by hand (download the new release, keep models/, outputs/ and user/)": "эта студия — не git-клон: обновляй вручную (скачай новый релиз, оставь models/, outputs/ и user/)",
"The studio's 💎 sets": "💎-наборы студии",
"Takes made with this studio and approved by its author, to hear what YuE2 does and make it again: instruments, styles and voices, each with its whole request. You do not have these yet:": "Семплы, сделанные в этой студии и одобренные её автором, — чтобы услышать, что умеет YuE2, и повторить: инструменты, стили и голоса, каждый со своим полным запросом. Этих у тебя пока нет:",
"Each comes as a workspace of its own; only what you pick is downloaded.": "Каждый приходит своим пространством; скачивается только то, что выберешь.",
"Skipped {0}: the next release will be offered": "{0} пропущена: будет предложен следующий релиз",
"Reload the page?": "Перезагрузить страницу?",
"It takes: the boxes' undo history, a lifted frame, the music playing, a writer's answer still on its way, an upload under way.\n\nIt keeps: the song in the form (its words and its knobs), a run under way (it comes back with its clock), the library, the Writer's notebook.\n\nCtrl+F5 reloads at once.": "Она заберёт: историю отмен в полях, поднятую рамку, играющую музыку, ответ писателя, который ещё в пути, идущую загрузку.\n\nОна сохранит: песню в форме (её слова и ручки), идущий ран (он вернётся со своими часами), библиотеку, блокнот Писателя.\n\nCtrl+F5 перезагружает сразу.",
"It takes: the boxes' undo history, a lifted frame, the music playing, a writer's answer still on its way, an upload under way.\n\nIt keeps: the song in the form (its words and its knobs), a run under way (it comes back with its clock), the library, the Writer's notebook.\n\nSave to the Writer keeps this song there as well before the reload: a new version of the document in hand, or a document of its own.\n\nCtrl+F5 reloads at once.": "Она заберёт: историю отмен в полях, поднятую рамку, играющую музыку, ответ писателя, который ещё в пути, идущую загрузку.\n\nОна сохранит: песню в форме (её слова и ручки), идущий ран (он вернётся со своими часами), библиотеку, блокнот Писателя.\n\n«Сохранить в Писателя» перед перезагрузкой сохранит эту песню и там: новой версией документа в руках или отдельным документом.\n\nCtrl+F5 перезагружает сразу.",
"Reset the output to the defaults?": "Сбросить вывод к умолчаниям?",
"WAV 24-bit, {#0} denoising steps, the midpoint solver, the songs up to {1}: what is set here now is kept nowhere else.": "WAV 24 бита, {#0} шагов очистки от шума, решатель midpoint, песни до {1}: то, что выставлено здесь сейчас, больше нигде не хранится.",
"WAV 24-bit, {#0} denoising steps, the AB2 solver, the songs up to {1}: what is set here now is kept nowhere else.": "WAV 24 бита, {#0} шагов очистки от шума, решатель AB2, песни до {1}: то, что выставлено здесь сейчас, больше нигде не хранится.",
"Output reset: WAV 24-bit, {#0} denoising steps, the midpoint solver, the songs up to {1}": "Вывод сброшен: WAV 24 бита, {#0} шагов очистки от шума, решатель midpoint, песни до {1}",
"Output reset: WAV 24-bit, {#0} denoising steps, the AB2 solver, the songs up to {1}": "Вывод сброшен: WAV 24 бита, {#0} шагов очистки от шума, решатель AB2, песни до {1}",
"Reset sampling to the defaults?": "Сбросить сэмплинг к умолчаниям?",
"The values set here now are kept nowhere else.": "Значения, выставленные здесь сейчас, больше нигде не хранятся.",
"Put the sliders back to the tuned defaults?": "Вернуть слайдеры к настроенным умолчаниям?",
"The sampling values they set now are kept nowhere else.": "Значения сэмплинга, которые они выставили, больше нигде не хранятся.",
"Put the look options and the fonts back to the app's own?": "Вернуть настройки вида и шрифты к родным для приложения?",
"The theme stays; the fonts and options chosen now are kept nowhere else.": "Тема останется; выбранные сейчас шрифты и настройки больше нигде не хранятся.",
"Clear the words?": "Очистить слова?",
"The title, style, lyrics, score, both seeds and loaded music codes go. The mode, sampling, LoRAs and Sound and output stay as they are; New song puts the mode, sampling and LoRAs back to the defaults too.": "Уйдут название, стиль, текст, партитура, оба сида и загруженные музыкальные коды. Режим, сэмплинг, LoRA и «Звук и вывод» останутся как есть; «Новая песня» вернёт к умолчаниям и режим, сэмплинг и LoRA.",
"Cleared: the words, the score, the seeds and loaded codes; the mode, knobs and LoRAs stay": "Очищено: слова, партитура, сиды и загруженные коды; режим, ручки и LoRA остаются",
"Replace the score in the form with the example?": "Заменить партитуру в форме примером?",
"The score there now is kept nowhere else: save the song first (the Save button above) to keep it.": "Нынешняя партитура больше нигде не хранится: сначала сохрани песню (кнопка «Сохранить» выше), чтобы её сберечь.",
"Remove the score from the form?": "Убрать партитуру из формы?",
