"Create a new ABC score?": "Создать новую ABC-партитуру?",
"The score now in the form is written over by the one planned from the style and the lyrics.": "Партитура, что сейчас в форме, будет заменена той, что спланирована по стилю и тексту.",
"Put {0} in place of the lyrics?": "Поставить {0} вместо текста?",
"The words now in the box go; Ctrl+Z in the box brings them back.": "Слова, что сейчас в поле, уйдут; Ctrl+Z в поле вернёт их.",
"{0} is not UTF-8 text: save it as UTF-8 and open it again": "{0} — не текст UTF-8: сохрани его в UTF-8 и открой снова",
