"a «(» not closed on its line": "«(» не закрыта на своей строке",
"Generate on the score in the form, or write a new one?": "Генерировать по партитуре в форме или написать новую?",
"The adapters differ from those that wrote this score.": "Адаптеры не те, что писали эту партитуру.",
"A score follows the adapters it was written with: at other strengths the music may part from it, Industrial Rock and instrumentals most.": "Партитура следует адаптерам, с которыми она написана: на других силах музыка может от неё отойти, больше всего в Industrial Rock и инструменталах.",
"On this score: the music follows it bar by bar. A new score: the song model writes one from the style and the lyrics, and this one goes.": "«По этой партитуре»: музыка идёт за ней такт за тактом. «Новая партитура»: модель песни напишет новую по стилю и тексту, а эта уйдёт.",
"Written with:": "Написана с:",
