"no adapters": "без адаптеров",
"At other strengths the music may part from the score (Industrial Rock and instrumentals most): set them back, or plan it anew.": "На других силах музыка может отойти от партитуры (больше всего в Industrial Rock и инструменталах): верни их или спланируй её заново.",
"In Full the score stays open while it holds one: empty it, or choose another mode, to fold it": "В Full партитура остаётся открытой, пока в ней что-то есть: очисти её или выбери другой режим, чтобы свернуть",
