"Out of GPU memory for the sound: {#0} of {#1} GB free when {#2} variations of {#3} s needed more. A smaller copy of the model (Q8_0) or fewer probes at once leaves it room.": "Не хватило памяти GPU для звука: свободно {#0} из {#1} ГБ, а вариациям ({#2}) по {#3} с нужно было больше. Место оставит меньшая копия модели (Q8_0) или меньше проб за раз.",
