"Photos, also JPEG-compressed or a little blurred: detailed and natural. The studio's default; slow.": "Фото, в том числе сжатые JPEG или слегка размытые: детально и естественно. По умолчанию в студии; медленный.",
"Clean photos (not compressed, not blurred): the most faithful detail on good input. Slow.": "Чистые фото (без сжатия и размытия): самая верная деталь на хорошем исходнике. Медленный.",
"Photos taken from the web: JPEG or WebP compression, blur and noise mended as it upscales. Slow.": "Фото из интернета: сжатие JPEG или WebP, размытие и шум чинятся по ходу апскейла. Медленный.",
"Photos with JPEG compression; keeps the grain and the noise. The slowest here, and in full precision only.": "Фото со сжатием JPEG; сохраняет зерно и шум. Самый медленный здесь, и только в полной точности.",
"Degraded photos, faces too: a large model trained on blur, noise and compression. Slow, and the heaviest on the card.": "Испорченные фото, лица тоже: большая модель, обученная на размытии, шуме и сжатии. Медленный и самый тяжёлый для карты.",
"Photos with JPEG compression and blur: a large model for realistic detail. Slow and heavy.": "Фото со сжатием JPEG и размытием: большая модель для реалистичной детали. Медленный и тяжёлый.",
