"Photos, quick: mends strongly (smoother). The first pass of Viktor's ComfyUI chain.": "Фото, быстро: чинит сильно (глаже). Первый проход цепочки Виктора в ComfyUI.",
"Realistic pictures, best on faces, hair and nature; a soft, natural look with few artifacts, for fairly clean input (not grainy). Quick. Non-commercial.": "Реалистичные картинки, лучше всего лица, волосы и природа; мягкий естественный вид с малым числом артефактов, для довольно чистого исходника (не зернистого). Быстрый. Некоммерческая лицензия.",
"ClearReality's softer sister: kinder to rendered and game pictures, weaker on real photos. Quick. Non-commercial.": "Более мягкая сестра ClearReality: добрее к рендерам и игровым картинкам, слабее на настоящих фото. Быстрый. Некоммерческая лицензия.",
"Realistic photos with noise and compression. Quick.": "Реалистичные фото с шумом и сжатием. Быстрый.",
