"Drag: more paper or more roll · a double click: as at first": "Тяни: больше бумаги или больше ролла · двойной щелчок: как было",
"A MIDI keyboard: its pitch wheel runs the cursor through time, its modulation wheel sets a new note's length": "MIDI-клавиатура: колесо высоты ведёт курсор по времени, колесо модуляции задаёт длину новой ноты",
"{0} BPM · free tempo": "{0} BPM · свободный темп",
"{0} BPM": "{0} BPM",
"To the start": "В начало",
