"The take in hand: what every step starts from. A click opens the Takes, to pick another": "Семпл в руке: с него начинается каждый шаг. Щелчок открывает Семплы, чтобы взять другой",
"The chain: its profile, Run the chain and On the workspace…; it runs the way drawn thick": "Цепочка: её профиль, «Запустить цепочку» и «На пространстве…»; она гонит путь, нарисованный жирным",
"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "Трек откуда угодно (WAV, FLAC, MP3…) в библиотеку как семпл с пометкой импорта; путь, проведённый отсюда, сам идёт на каждом следующем импорте",
"Every file made from this take, each under the one it came from: play, compare, rate, delete": "Каждый файл, сделанный из этого семпла, под тем, из которого вышел: слушать, сравнивать, оценивать, удалять",
"The spectrum of the take or of a file made from it: how loud each band is, over time": "Спектр семпла или сделанного из него файла: насколько громка каждая полоса во времени",
"Faults measured in a file: clicks, clipping, the frame buzz, a hum": "Изъяны, измеренные в файле: щелчки, перегруз, жужжание кадров, фон",
"The lyrics held against what is sung (Whisper): which lines came and which did not": "Лирика против спетого (Whisper): какие строки пришли, а какие нет",
"The frame buzz of YuE2's sound out of the take: needed for every YuE2 take, off for a track from elsewhere": "Жужжание кадров звука YuE2 вон из семпла: нужно каждому семплу YuE2, выключено для чужого трека",
"UniverSR redraws the top of the spectrum above a cutoff, the original kept below it": "UniverSR заново рисует верх спектра выше среза, ниже остаётся оригинал",
"The file split into stems: four, six, eight, or the voice and the rest": "Файл, разложенный на стемы: четыре, шесть, восемь или голос и остальное",
"The stems on lanes: levels, versions, buses and automation, then a mix": "Стемы на дорожках: уровни, версии, шины и автоматика, потом микс",
"The Digital Gateway: tape, console and tube in numbers, on a file or a mix": "Цифровой шлюз: лента, пульт и лампа в цифрах, на файле или миксе",
"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "Debunker: файл или набор стемов сбалансирован, сжат, тонирован и выведен к громкости",
