"Playlist · {#0} / {#1}": "Плейлист · {0} / {1}",
"Without a note": "Без заметки",
// HERESY 1734: why the wave's section edits are greyed
"Sections and lyrics on the wave are off (the player's switch)": "Секции и лирика на волне выключены (переключатель плеера)",
"These are the score's marks: Find the sections by ear first (in this menu)": "Это метки партитуры: сначала «Найти секции на слух» (в этом меню)",
"No sections on the wave yet: Find the sections by ear (in this menu)": "На волне ещё нет секций: «Найти секции на слух» (в этом меню)",
"No section under the pointer": "Под указателем нет секции",
"The rest of a part sung anew: the pointer over the part itself": "Хвост спетой заново части: наведи на саму часть",
"No words here, an instrumental part: the pointer over a sung section": "Здесь нет слов, это инструментальная часть: наведи на спетую секцию",
